<form class="nfm" id="{{ $nf }}" data-id="{{ (int)$cid }}" style="margin-top:8px;border:1px solid #FFE3D1;background:#FFF8F3;border-radius:12px;padding:10px 12px;font-size:12.5px">@csrf
<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px">@foreach($tpl as $i => $t)<button type="button" data-tpl='@json($t)' style="border:1px solid #FDC2A5;background:#fff;border-radius:999px;padding:3px 10px;font-size:11.5px;cursor:pointer">{{ $t[0] }}</button>@endforeach</div>
<input name="title" maxlength="120" placeholder="Title" required style="width:100%;margin-bottom:6px">
<textarea name="body" maxlength="400" rows="2" placeholder="Message" required style="width:100%;margin-bottom:6px"></textarea>
<div style="display:flex;gap:6px;flex-wrap:wrap"><select name="type" style="flex:1;min-width:140px"><option value="special_discount">Special offer</option><option value="coupon">Coupon</option><option value="new_arrival">New arrival</option><option value="support_reply">Message from support</option></select><input name="url" placeholder="Link (e.g. /account/orders)" style="flex:1;min-width:140px"></div>
<div style="display:flex;gap:8px;align-items:center;margin-top:8px"><button type="submit">🔔 Send to {{ $name ?? 'customer' }}</button><span class="nfr" style="font-size:12px"></span></div></form>
<script>(function(){var f=document.getElementById(@json($nf));if(!f||f.__b)return;f.__b=1;
f.querySelectorAll('[data-tpl]').forEach(function(b){b.onclick=function(){var t=JSON.parse(b.getAttribute('data-tpl'));f.title.value=t[0];f.body.value=t[1];f.url.value=t[2];f.type.value=t[3]}});
f.onsubmit=function(e){e.preventDefault();var r=f.querySelector('.nfr'),bt=f.querySelector('[type=submit]');bt.disabled=true;r.style.color='#6B7280';r.textContent='পাঠানো হচ্ছে…';
var tk=document.querySelector('meta[name=csrf-token]'),fd=new FormData(f);
fetch('/admin/app-users/'+f.getAttribute('data-id')+'/notify',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','X-CSRF-TOKEN':tk?tk.content:fd.get('_token')||''},body:fd}).then(function(x){return x.json().catch(function(){return{}}).then(function(j){j._s=x.status;return j})}).then(function(j){bt.disabled=false;var ok=j.ok;r.style.color=ok?'#166534':'#B45309';r.textContent=j.msg||(j.errors?Object.values(j.errors)[0][0]:'পাঠানো যায়নি')}).catch(function(){bt.disabled=false;r.style.color='#B91C1C';r.textContent='নেটওয়ার্ক সমস্যা, আবার চেষ্টা করুন'})}})();</script>
